"""Self-contained HTML report: inline CSS, print-friendly, brandable, EN/IT."""
from __future__ import annotations

import html
import json

SEV_COLORS = {
    "CRITICAL": "#a4080e", "HIGH": "#d13b10", "MEDIUM": "#c78a03",
    "LOW": "#3a7a2a", "INFO": "#5b6470",
}

STR = {
    "en": {
        "title": "Security scan report",
        "generated_by": "generated by {name}",
        "prepared_by": "prepared by {agency}",
        "scope": "Scope & authorization",
        "target": "Target", "ports": "Ports",
        "authorized_for": "Authorized for", "scope_label": "Scope",
        "issued": "Issued", "expires": "Expires",
        "scan_started": "Scan started", "scan_finished": "Scan finished",
        "skipped": "Checks skipped (tools not available on this machine)",
        "errors": "Adapter errors",
        "findings": "Findings ({n})",
        "no_findings": "No findings from the enabled checks.",
        "what_this_means": "What this means",
        "fix": "Fix",
        "refs": "Refs",
        "footer": ("Every finding above was verified against the authorized "
                   "target only. Reports are backed by a signed, expiring "
                   "authorization record. Scan only what you are authorized "
                   "to test."),
    },
    "it": {
        "title": "Report di scansione di sicurezza",
        "generated_by": "generato da {name}",
        "prepared_by": "preparato da {agency}",
        "scope": "Perimetro e autorizzazione",
        "target": "Obiettivo", "ports": "Porte",
        "authorized_for": "Autorizzato da", "scope_label": "Perimetro",
        "issued": "Rilasciato", "expires": "Scade",
        "scan_started": "Scansione iniziata", "scan_finished": "Scansione finita",
        "skipped": "Controlli non eseguiti (strumenti non disponibili su questa macchina)",
        "errors": "Errori degli adattatori",
        "findings": "Risultati ({n})",
        "no_findings": "Nessun risultato dai controlli attivi.",
        "what_this_means": "Cosa significa",
        "fix": "Rimedio",
        "refs": "Riferimenti",
        "footer": ("Ogni risultato è stato verificato solo sull'obiettivo "
                   "autorizzato. I report sono coperti da un'autorizzazione "
                   "firmata con scadenza. Scansiona solo ciò che sei "
                   "autorizzato a testare."),
    },
}

_CSS = """
:root{--ink:#1c2430;--muted:#5b6470;--line:#dfe3ea;--bg:#fbfbf9;--accent:#23408e}
*{box-sizing:border-box}
body{font:15px/1.55 -apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;
color:var(--ink);background:#fff;margin:0}
.wrap{max-width:880px;margin:0 auto;padding:40px 28px}
h1{font-size:26px;margin:0 0 4px}
h2{font-size:18px;margin:34px 0 10px;border-bottom:2px solid var(--accent);
padding-bottom:6px}
.logo{font-weight:800;letter-spacing:1px;color:var(--accent);font-size:13px;
text-transform:uppercase;margin-bottom:14px}
.muted{color:var(--muted)}
.meta{display:grid;grid-template-columns:1fr 1fr;gap:4px 24px;margin:18px 0;font-size:13.5px}
.meta div{border-bottom:1px solid var(--line);padding:5px 0}
.meta b{font-weight:600}
.chips{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0 4px}
.chip{color:#fff;font-weight:700;font-size:12.5px;padding:4px 10px;border-radius:20px}
.summary{background:var(--bg);border:1px solid var(--line);border-radius:8px;
padding:14px 16px;margin:18px 0}
.notice{background:#fdf6ec;border:1px solid #ead9bd;border-radius:8px;
padding:10px 14px;margin:12px 0;font-size:13.5px}
.card{border:1px solid var(--line);border-left:5px solid var(--muted);
border-radius:8px;padding:14px 16px;margin:12px 0}
.card .head{display:flex;justify-content:space-between;gap:12px;align-items:baseline}
.card h3{font-size:15.5px;margin:0}
.badge{color:#fff;font-size:11px;font-weight:800;letter-spacing:.6px;
padding:2px 8px;border-radius:4px;white-space:nowrap}
.card .src{font-size:12px;color:var(--muted);margin:4px 0 8px}
pre{background:#f4f5f7;border:1px solid var(--line);border-radius:6px;
padding:8px 10px;font-size:12.5px;overflow-x:auto;white-space:pre-wrap;
word-break:break-word;margin:6px 0}
.remediation,.meaning{font-size:14px;margin:6px 0 0}
.refs{font-size:12px;margin-top:6px}
footer{margin-top:40px;border-top:1px solid var(--line);padding-top:14px;
font-size:12px;color:var(--muted)}
@media print{.wrap{max-width:none;padding:0}}
"""


def _chip(label: str, count: int) -> str:
    return (f'<span class="chip" style="background:{SEV_COLORS[label]}">'
            f'{label} {count}</span>')


def _card(f: dict, t: dict) -> str:
    sev = f["severity"]
    color = SEV_COLORS.get(sev, "#5b6470")
    meta_all = f.get("metadata") or {}
    meaning = meta_all.get("plain_meaning", "")
    meaning_html = (f'<p class="meaning"><b>{html.escape(t["what_this_means"])}:'
                    f'</b> {html.escape(str(meaning))}</p>') if meaning else ""
    meta_left = {k: v for k, v in meta_all.items() if k != "plain_meaning"}
    meta = (f'<div class="src">meta: '
            f'{html.escape(json.dumps(meta_left)[:160])}</div>') if meta_left else ""
    evidence = ""
    if f.get("evidence"):
        evidence = f"<pre>{html.escape(str(f['evidence']))}</pre>"
    refs = ""
    if f.get("references"):
        links = " ".join(
            f'<a href="{html.escape(r)}">{html.escape(r)}</a>'
            for r in f["references"][:3]
        )
        refs = f'<div class="refs">{html.escape(t["refs"])}: {links}</div>'
    return f"""
<div class="card" style="border-left-color:{color}">
  <div class="head"><h3>{html.escape(f['title'])}</h3>
  <span class="badge" style="background:{color}">{sev}</span></div>
  <div class="src">{html.escape(f['source'])} · {html.escape(f['target'])}
   · {html.escape(f.get('category',''))} · {html.escape(f.get('id',''))}</div>
  {evidence}{meta}{meaning_html}
  <p class="remediation"><b>{html.escape(t['fix'])}:</b> {html.escape(f.get('remediation') or '')}</p>
  {refs}
</div>"""


def render(result: dict, branding: dict | None = None) -> str:
    branding = branding or {}
    lang = branding.get("language", "en")
    if lang not in STR:
        raise ValueError(f"unknown report language: {lang!r}")
    t = STR[lang]
    agency = branding.get("agency_name", "")
    logo = branding.get("logo_text", "secscan")
    accent = branding.get("accent_color", "#23408e")
    css = _CSS.replace("--accent:#23408e", f"--accent:{accent}")

    counts = result.get("counts", {})
    chips = "".join(_chip(s, counts.get(s, 0)) for s in
                    ("CRITICAL", "HIGH", "MEDIUM", "LOW", "INFO"))
    authz = result.get("authorization", {})

    byline = t["generated_by"].format(name=html.escape(logo))
    if agency:
        byline += f' · {t["prepared_by"].format(agency=html.escape(agency))}'

    skipped = result.get("skipped", [])
    notice = ""
    if skipped:
        items = "".join(
            f"<li><b>{html.escape(s['adapter'])}</b>: {html.escape(s['reason'])}</li>"
            for s in skipped
        )
        notice = (f'<div class="notice"><b>{html.escape(t["skipped"])}:</b> '
                  f'<ul>{items}</ul></div>')
    errors = result.get("errors", [])
    err_notice = ""
    if errors:
        items = "".join(
            f"<li><b>{html.escape(e['adapter'])}</b>: "
            f"{html.escape(e['error'])}</li>" for e in errors
        )
        err_notice = (f'<div class="notice"><b>{html.escape(t["errors"])}:</b> '
                      f'<ul>{items}</ul></div>')

    findings = result.get("findings", [])
    cards = "".join(_card(f, t) for f in findings) or \
        f"<p class='muted'>{html.escape(t['no_findings'])}</p>"

    footer = branding.get("footer") or t["footer"]
    return f"""<!doctype html>
<html lang="{lang}"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>{html.escape(logo)} — {html.escape(t['title'])} — {html.escape(result.get('host',''))}</title>
<style>{css}</style></head>
<body><div class="wrap">
<div class="logo">{html.escape(logo)}</div>
<h1>{html.escape(t['title'])}</h1>
<div class="muted">{byline}</div>
<div class="chips">{chips}</div>
<div class="summary">{html.escape(result.get('summary',''))}</div>
<h2>{html.escape(t['scope'])}</h2>
<div class="meta">
  <div><b>{html.escape(t['target'])}</b> {html.escape(result.get('host',''))}</div>
  <div><b>{html.escape(t['ports'])}</b> {html.escape(', '.join(map(str, result.get('ports', []))))}</div>
  <div><b>{html.escape(t['authorized_for'])}</b> {html.escape(str(authz.get('owner','?')))}</div>
  <div><b>{html.escape(t['scope_label'])}</b> {html.escape(str(authz.get('scope','?')))}</div>
  <div><b>{html.escape(t['issued'])}</b> {html.escape(str(authz.get('issued_at','?')))}</div>
  <div><b>{html.escape(t['expires'])}</b> {html.escape(str(authz.get('expires_at','?')))}</div>
  <div><b>{html.escape(t['scan_started'])}</b> {html.escape(str(result.get('started_at','?')))}</div>
  <div><b>{html.escape(t['scan_finished'])}</b> {html.escape(str(result.get('finished_at','?')))}</div>
</div>
{notice}{err_notice}
<h2>{html.escape(t['findings'].format(n=len(findings)))}</h2>
{cards}
<footer>{html.escape(footer)}</footer>
</div></body></html>"""
